import { SemanticContent } from "@/components/ui/semantic-content"
import { StatusMark } from "@/components/ui/status-mark"

type Step = { title: string; description?: string; state?: "done" | "current" | "upcoming" }

const tone = { done: "success", current: "info", upcoming: "neutral" } as const
const stateLabel = { done: "Done", current: "In progress", upcoming: "Up next" } as const

/** Numbered steps (after the diceui stepper anatomy) with a status mark per step. */
export default function Steps({
  heading = "How it works",
  steps = [
    { title: "Pick a starting point", description: "Choose a frame and the sections it needs.", state: "done" },
    { title: "Fill the copy", description: "Every slot gets resolved, reviewed text.", state: "current" },
    { title: "Publish", description: "Assemble the page and ship it.", state: "upcoming" },
  ],
}: {
  heading?: string
  steps?: Step[]
}) {
  return (
    <section data-slot="steps" className="py-12">
      <div className="mx-auto max-w-5xl px-6">
        <SemanticContent as="h2" className="text-2xl">{heading}</SemanticContent>
        <ol className="mt-8 grid gap-6 md:grid-cols-3">
          {steps.map((s, i) => {
            const state = s.state ?? "upcoming"
            return (
              <li key={s.title} aria-current={state === "current" ? "step" : undefined} className="flex flex-col gap-3 border-t border-border pt-4">
                <div className="flex items-center justify-between gap-2">
                  <span className="font-mono text-sm text-muted-foreground tabular-nums">{String(i + 1).padStart(2, "0")}</span>
                  <StatusMark tone={tone[state]}>{stateLabel[state]}</StatusMark>
                </div>
                <SemanticContent as="h3" className="text-lg">{s.title}</SemanticContent>
                {s.description && <SemanticContent as="p" className="text-sm text-muted-foreground">{s.description}</SemanticContent>}
              </li>
            )
          })}
        </ol>
      </div>
    </section>
  )
}
